<?php $pageTitle='CuePOS Platform';require_once __DIR__.'/../includes/header.php';requirePlatformAdmin();$db=getDB();$stats=[];foreach(['clubs'=>'SELECT COUNT(*) FROM clubs','trials'=>"SELECT COUNT(*) FROM subscriptions WHERE status='trial' AND trial_ends_at>=NOW()",'paid'=>"SELECT COUNT(*) FROM subscriptions WHERE status='active'",'leads'=>'SELECT COUNT(*) FROM demo_requests WHERE status=\'new\''] as $k=>$sql){try{$stats[$k]=(int)$db->query($sql)->fetchColumn();}catch(Throwable $e){$stats[$k]=0;}}$clubs=$db->query("SELECT c.*,p.name plan_name,s.status subscription_status,s.trial_ends_at FROM clubs c LEFT JOIN subscriptions s ON s.id=(SELECT ss.id FROM subscriptions ss WHERE ss.club_id=c.id ORDER BY ss.id DESC LIMIT 1) LEFT JOIN plans p ON p.id=s.plan_id ORDER BY c.created_at DESC LIMIT 100")->fetchAll(); ?><main class="pt-20 min-h-screen"><div class="max-w-screen-2xl mx-auto p-4 lg:p-6"><div class="flex justify-between items-center"><div><p class="text-cue text-xs uppercase font-bold tracking-widest">Platform owner</p><h1 class="text-2xl font-bold mt-1">CuePOS SaaS Console</h1><p class="text-slate-400 text-sm mt-1">Monitor global club workspaces, trials and subscription readiness.</p></div><a href="<?=url('platform/settings.php')?>" class="btn-primary"><i class="fa-solid fa-gear mr-1"></i>Platform settings</a></div><div class="grid grid-cols-2 xl:grid-cols-4 gap-4 mt-6"><?php foreach([['Club workspaces',$stats['clubs'],'text-green-400'],['Active trials',$stats['trials'],'text-amber-300'],['Paid subscriptions',$stats['paid'],'text-blue-300'],['New demo leads',$stats['leads'],'text-purple-300']] as [$l,$v,$c]): ?><div class="card"><p class="text-xs uppercase text-slate-400"><?=$l?></p><p class="text-3xl font-extrabold mt-2 <?=$c?>"><?=$v?></p></div><?php endforeach; ?></div><section class="card mt-5 overflow-x-auto"><h2 class="font-bold mb-4">Club tenants</h2><table class="data-table w-full"><thead><tr><th>Club</th><th>Tenant URL slug</th><th>Country</th><th>Status</th><th>Plan</th><th>Trial ends</th><th>Created</th></tr></thead><tbody><?php foreach($clubs as $c): ?><tr><td class="font-semibold"><?=sanitize($c['name'])?></td><td><?=sanitize($c['slug']?:'—')?></td><td><?=sanitize($c['country_code']?:'—')?></td><td><span class="text-xs px-2 py-1 rounded bg-slate-700"><?=sanitize($c['tenant_status']??'active')?></span></td><td><?=sanitize($c['plan_name']?:'—')?></td><td><?=$c['trial_ends_at']?date('d M Y',strtotime($c['trial_ends_at'])):'—'?></td><td><?=date('d M Y',strtotime($c['created_at']))?></td></tr><?php endforeach; ?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
